297	func TestReverseReservation(t *testing.T) {
298		store := testStore(t)
299		from, to := activeWindow()
300		id := uniqueID(t)
301		mustCreate(t, store, id, 100, from, to)
302		ctx := context.Background()
303	
304		if _, _, err := store.CreateReservation(ctx, id, "res-1", 30); err != nil {
305			t.Fatalf("reserve: %v", err)
306		}
307		if _, err := store.SettleReservation(ctx, id, "res-1", ActionConfirm); err != nil {
308			t.Fatalf("confirm: %v", err)
309		}
310	
311		reversal, created, err := store.ReverseReservation(ctx, id, "res-1", "corr-1")
312		if err != nil || !created {
313			t.Fatalf("reverse: %+v created=%v err=%v", reversal, created, err)
314		}
315		if reversal.ReversalID != "corr-1" || reversal.ReservationID != "res-1" ||
316			reversal.Amount != 30 || reversal.Status != StatusReversed || reversal.SettledAt == nil {
317			t.Fatalf("reversal record: %+v", reversal)
318		}
319		view, err := store.GetView(ctx, id)
320		if err != nil {
321			t.Fatalf("view: %v", err)
322		}
323		if view.UsedAmount != 0 || view.ReservedAmount != 0 || view.AvailableAmount != 100 {
324			t.Fatalf("quota after reversal: %+v", view)
325		}
326		// Both the original reservation and the reversal appear in the list.
327		if len(view.Reservations) != 2 {
328			t.Fatalf("reservation list: %+v", view.Reservations)
329		}
330		original, entry := view.Reservations[0], view.Reservations[1]
331		if original.ReservationID != "res-1" || original.Status != StatusConfirmed || original.SettledAt == nil {
332			t.Fatalf("original reservation altered: %+v", original)
333		}
334		if entry.ReservationID != "corr-1" || entry.Amount != 30 ||
335			entry.Status != StatusReversed || entry.SettledAt == nil {
336			t.Fatalf("reversal entry: %+v", entry)
337		}
338	
339		// Replaying the same correction identifier returns the original result
340		// and does not refund again.
341		replay, created, err := store.ReverseReservation(ctx, id, "res-1", "corr-1")
342		if err != nil || created {
343			t.Fatalf("replay: %+v created=%v err=%v", replay, created, err)
344		}
345		if replay.ReversalID != reversal.ReversalID || replay.ReservationID != reversal.ReservationID ||
346			replay.Amount != reversal.Amount || replay.Status != reversal.Status ||
347			!replay.CreatedAt.Equal(reversal.CreatedAt) || !replay.SettledAt.Equal(*reversal.SettledAt) {
348			t.Fatalf("replay should return the original: %+v vs %+v", replay, reversal)
349		}
350		view, _ = store.GetView(ctx, id)
351		if view.UsedAmount != 0 || view.AvailableAmount != 100 || len(view.Reservations) != 2 {
352			t.Fatalf("replay refunded again: %+v", view)
353		}
354	
355		// The same correction identifier targeting another reservation fails.
356		if _, _, err := store.CreateReservation(ctx, id, "res-2", 10); err != nil {
357			t.Fatalf("reserve: %v", err)
358		}
359		if _, err := store.SettleReservation(ctx, id, "res-2", ActionConfirm); err != nil {
360			t.Fatalf("confirm: %v", err)
361		}
362		_, _, err = store.ReverseReservation(ctx, id, "res-2", "corr-1")
363		wantCode(t, err, CodeReservationParamChanged)
364		view, _ = store.GetView(ctx, id)
365		if view.UsedAmount != 10 || len(view.Reservations) != 3 {
366			t.Fatalf("param mismatch changed state: %+v", view)
367		}
368	
369		// The same reservation cannot be reversed twice.
370		_, _, err = store.ReverseReservation(ctx, id, "res-1", "corr-2")
371		wantCode(t, err, CodeReservationReversed)
372		view, _ = store.GetView(ctx, id)
373		if view.UsedAmount != 10 || view.AvailableAmount != 90 || len(view.Reservations) != 3 {
374			t.Fatalf("second reversal changed state: %+v", view)
375		}
376	}
