446	func TestConcurrentReversalsSettleOnce(t *testing.T) {
447		store := testStore(t)
448		from, to := activeWindow()
449		id := uniqueID(t)
450		const quota = 100
451		mustCreate(t, store, id, quota, from, to)
452		ctx := context.Background()
453		if _, _, err := store.CreateReservation(ctx, id, "res-1", 40); err != nil {
454			t.Fatalf("reserve: %v", err)
455		}
456		if _, err := store.SettleReservation(ctx, id, "res-1", ActionConfirm); err != nil {
457			t.Fatalf("confirm: %v", err)
458		}
459	
460		const workers = 8
461		var wg sync.WaitGroup
462		results := make(chan error, workers*2)
463		for w := 0; w < workers; w++ {
464			wg.Add(1)
465			go func(w int) {
466				defer wg.Done()
467				rid := fmt.Sprintf("corr-%d", w)
468				// Each worker reverses once and replays the same correction.
469				_, _, err := store.ReverseReservation(ctx, id, "res-1", rid)
470				results <- err
471				_, _, err = store.ReverseReservation(ctx, id, "res-1", rid)
472				results <- err
473			}(w)
474		}
475		wg.Wait()
476		close(results)
477		successes := 0
478		for err := range results {
479			if err == nil {
480				successes++
481				continue
482			}
483			var domainErr *Error
484			if !errors.As(err, &domainErr) || domainErr.Code != CodeReservationReversed {
485				t.Fatalf("unexpected concurrent failure: %v", err)
486			}
487		}
488		// Exactly one correction took effect; its replay succeeded too.
489		if successes != 2 {
490			t.Fatalf("want 2 successful calls (one reversal + its replay), got %d", successes)
491		}
492		view, err := store.GetView(ctx, id)
493		if err != nil {
494			t.Fatalf("view: %v", err)
495		}
496		if view.UsedAmount != 0 || view.AvailableAmount != quota || len(view.Reservations) != 2 {
497			t.Fatalf("concurrent reversals broke state: %+v", view)
498		}
499	}
500	
501	func TestStateSurvivesReconnection(t *testing.T) {
502		store := testStore(t)
503		from, to := activeWindow()
504		id := uniqueID(t)
505		mustCreate(t, store, id, 100, from, to)
506		ctx := context.Background()
507		if _, _, err := store.CreateReservation(ctx, id, "res-1", 30); err != nil {
508			t.Fatalf("reserve: %v", err)
509		}
510		if _, err := store.SettleReservation(ctx, id, "res-1", ActionConfirm); err != nil {
511			t.Fatalf("confirm: %v", err)
512		}
513		if _, _, err := store.ReverseReservation(ctx, id, "res-1", "corr-1"); err != nil {
514			t.Fatalf("reverse: %v", err)
515		}
516	
517		// A fresh pool over the same database simulates a service restart.
518		pool, err := pgxpool.New(ctx, os.Getenv("TEST_DATABASE_URL"))
519		if err != nil {
520			t.Fatalf("reconnect: %v", err)
521		}
522		defer pool.Close()
523		restarted := NewStore(pool)
524		view, err := restarted.GetView(ctx, id)
525		if err != nil {
526			t.Fatalf("view after restart: %v", err)
527		}
528		if view.UsedAmount != 0 || view.AvailableAmount != 100 || len(view.Reservations) != 2 ||
529			view.Reservations[0].Status != StatusConfirmed || view.Reservations[1].Status != StatusReversed {
530			t.Fatalf("state lost across restart: %+v", view)
531		}
532		// The correction identifier is still replayed, not re-applied.
533		replay, created, err := restarted.ReverseReservation(ctx, id, "res-1", "corr-1")
534		if err != nil || created || replay.Amount != 30 {
535			t.Fatalf("reversal replay after restart: %+v created=%v err=%v", replay, created, err)
536		}
537	}
